#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    const char *mode = argv[1];
    const char *in = argv[2];
    size_t len = strlen(in);
    if (len > 0x3FF) { // limit observed in the original binary
        puts("USAGE");
        return 0;
    }
    char out[2048];
    size_t outpos = 0;
    if (strcmp(mode, "escape") == 0) {
        for (size_t i = 0; i < len; ++i) {
            unsigned char c = (unsigned char)in[i];
            if (c == '\\') {
                out[outpos++] = '\\';
                out[outpos++] = '\\';
            } else if (c == '\n') {
                out[outpos++] = '\\';
                out[outpos++] = 'n';
            } else if (c == '\t') {
                out[outpos++] = '\\';
                out[outpos++] = 't';
            } else if (c == '"') {
                out[outpos++] = '\\';
                out[outpos++] = '"';
            } else {
                out[outpos++] = c;
            }
        }
        out[outpos] = '\0';
        puts(out);
    } else if (strcmp(mode, "unescape") == 0) {
        for (size_t i = 0; i < len; ) {
            if (in[i] == '\\' && i + 1 < len) {
                char nxt = in[i + 1];
                if (nxt == 'n') {
                    out[outpos++] = '\n';
                    i += 2;
                    continue;
                }
                if (nxt == 't') {
                    out[outpos++] = '\t';
                    i += 2;
                    continue;
                }
                if (nxt == '\\') {
                    out[outpos++] = '\\';
                    i += 2;
                    continue;
                }
                if (nxt == '"') {
                    out[outpos++] = '"';
                    i += 2;
                    continue;
                }
                // Unknown escape – copy the character after the backslash.
                out[outpos++] = nxt;
                i += 2;
            } else {
                out[outpos++] = in[i++];
            }
        }
        out[outpos] = '\0';
        puts(out);
    } else {
        puts("INVALID_MODE");
    }
    return 0;
}
}
